import { requireAdmin } from '../auth.js';
import { readMultipart, saveImage, deleteUpload } from '../files.js';
import { withStats } from '../../services/serialize.js';
import { approveOrder, rejectOrder, drawWinner, ApiError } from '../../services/orders.js';
import { startBroadcast, sendTest } from '../../services/broadcast.js';
import { config } from '../../config.js';
import { Lottery, BankAccount, Order, Ticket, User, Broadcast } from '../../models/index.js';

const isId = (s) => /^[a-f\d]{24}$/i.test(String(s));

export default async function adminRoutes(app) {
  app.addHook('preHandler', requireAdmin);

  // ---------- dashboard ----------
  app.get('/stats', async () => ({
    pending: await Order.countDocuments({ status: 'PENDING' }),
    approved: await Order.countDocuments({ status: 'APPROVED' }),
    ticketsTaken: await Ticket.countDocuments({ status: 'TAKEN' }),
    activeLotteries: await Lottery.countDocuments({ status: 'ACTIVE' }),
    users: await User.countDocuments(),
  }));

  // ---------- orders ----------
  app.get('/orders', async (req) => {
    const status = ['PENDING', 'APPROVED', 'REJECTED'].includes(req.query.status) ? req.query.status : null;
    const rows = await Order.find(status ? { status } : {})
      .sort({ createdAt: -1 })
      .limit(200)
      .populate('lottery', 'title carName')
      .populate('bankAccount', 'bankName');
    const tickets = await Ticket.find({ order: { $in: rows.map((o) => o._id) } }).select('order number');
    const byOrder = new Map();
    for (const t of tickets) {
      const k = String(t.order);
      if (!byOrder.has(k)) byOrder.set(k, []);
      byOrder.get(k).push(t.number);
    }
    return rows.map((o) => ({
      id: String(o._id),
      code: o.code,
      status: o.status,
      user: o.user,
      fullName: o.fullName,
      phone: o.phone,
      total: o.total,
      senderAccount: o.senderAccount || null,
      bank: o.bankAccount?.bankName || null,
      receiptUrl: o.receiptUrl,
      rejectReason: o.rejectReason || null,
      createdAt: o.createdAt,
      lottery: o.lottery ? `${o.lottery.title} (${o.lottery.carName})` : '-',
      numbers: (byOrder.get(String(o._id)) || []).sort((a, b) => a - b),
    }));
  });

  app.post('/orders/:id/approve', async (req) => {
    if (!isId(req.params.id)) throw new ApiError(404, 'not_found');
    await approveOrder(req.params.id);
    return { ok: true };
  });

  app.post('/orders/:id/reject', async (req) => {
    if (!isId(req.params.id)) throw new ApiError(404, 'not_found');
    const reason = String(req.body?.reason || '').trim().slice(0, 200);
    await rejectOrder(req.params.id, reason);
    return { ok: true };
  });

  // ---------- lotteries ----------
  app.get('/lotteries', async () => withStats(await Lottery.find().sort({ createdAt: -1 })));

  app.post('/lotteries', async (req) => {
    const { fields, file } = await readMultipart(req);
    if (!file) throw new ApiError(400, 'image_required');
    const totalTickets = Number(fields.totalTickets);
    const ticketPrice = Number(fields.ticketPrice);
    const endsAt = new Date(fields.endsAt);
    if (!fields.title?.trim() || !fields.carName?.trim() || !fields.carColor?.trim())
      throw new ApiError(400, 'missing_fields');
    if (!Number.isInteger(totalTickets) || totalTickets < 1 || totalTickets > config.maxTickets)
      throw new ApiError(400, 'tickets_1_to_4000');
    if (!Number.isFinite(ticketPrice) || ticketPrice < 1) throw new ApiError(400, 'bad_price');
    if (Number.isNaN(endsAt.getTime()) || endsAt <= new Date()) throw new ApiError(400, 'bad_end_date');

    const imageUrl = await saveImage(file, 'cars', { allowWebp: true });
    const lottery = await Lottery.create({
      title: fields.title.trim(),
      carName: fields.carName.trim(),
      carColor: fields.carColor.trim(),
      imageUrl,
      ticketPrice,
      totalTickets,
      endsAt,
      featured: fields.featured === 'true',
    });
    return withStats(lottery);
  });

  app.patch('/lotteries/:id', async (req) => {
    if (!isId(req.params.id)) throw new ApiError(404, 'not_found');
    const lottery = await Lottery.findById(req.params.id);
    if (!lottery) throw new ApiError(404, 'not_found');
    const { featured, status } = req.body || {};
    if (typeof featured === 'boolean') lottery.featured = featured;
    if (status === 'ACTIVE' || status === 'CLOSED') {
      if (lottery.status !== 'DRAWN') lottery.status = status;
    }
    await lottery.save();
    return withStats(lottery);
  });

  app.post('/lotteries/:id/draw', async (req) => {
    if (!isId(req.params.id)) throw new ApiError(404, 'not_found');
    const lottery = await drawWinner(req.params.id);
    return { winnerNumber: lottery.winnerNumber, winnerUser: lottery.winnerUser };
  });

  app.delete('/lotteries/:id', async (req) => {
    if (!isId(req.params.id)) throw new ApiError(404, 'not_found');
    const used = await Order.countDocuments({ lottery: req.params.id });
    if (used) throw new ApiError(409, 'lottery_has_orders');
    const lottery = await Lottery.findByIdAndDelete(req.params.id);
    if (lottery) await deleteUpload(lottery.imageUrl);
    return { ok: true };
  });

  // ---------- bank accounts ----------
  app.get('/banks', async () => {
    const rows = await BankAccount.find().sort({ sortOrder: 1, _id: 1 });
    return rows.map((b) => ({
      id: String(b._id),
      bankName: b.bankName,
      accountName: b.accountName,
      accountNumber: b.accountNumber,
      active: b.active,
      sortOrder: b.sortOrder,
    }));
  });

  app.post('/banks', async (req) => {
    const { bankName, accountName, accountNumber } = req.body || {};
    if (![bankName, accountName, accountNumber].every((s) => typeof s === 'string' && s.trim()))
      throw new ApiError(400, 'missing_fields');
    const count = await BankAccount.countDocuments();
    const b = await BankAccount.create({
      bankName: bankName.trim(),
      accountName: accountName.trim(),
      accountNumber: accountNumber.trim(),
      sortOrder: count,
    });
    return { id: String(b._id) };
  });

  app.patch('/banks/:id', async (req) => {
    if (!isId(req.params.id)) throw new ApiError(404, 'not_found');
    const b = await BankAccount.findById(req.params.id);
    if (!b) throw new ApiError(404, 'not_found');
    const { active, bankName, accountName, accountNumber } = req.body || {};
    if (typeof active === 'boolean') b.active = active;
    if (typeof bankName === 'string' && bankName.trim()) b.bankName = bankName.trim();
    if (typeof accountName === 'string' && accountName.trim()) b.accountName = accountName.trim();
    if (typeof accountNumber === 'string' && accountNumber.trim()) b.accountNumber = accountNumber.trim();
    await b.save();
    return { ok: true };
  });

  app.delete('/banks/:id', async (req) => {
    if (!isId(req.params.id)) throw new ApiError(404, 'not_found');
    await BankAccount.findByIdAndDelete(req.params.id);
    return { ok: true };
  });

  // ---------- announcements (photo + text to everyone who started the bot) ----------
  app.get('/broadcasts', async () => {
    const rows = await Broadcast.find().sort({ createdAt: -1 }).limit(20);
    return rows.map((b) => ({
      id: String(b._id),
      text: b.text,
      hasPhoto: b.hasPhoto,
      total: b.total,
      sent: b.sent,
      blocked: b.blocked,
      failed: b.failed,
      status: b.status,
      createdAt: b.createdAt,
    }));
  });

  app.post('/broadcast', async (req) => {
    const { fields, file } = await readMultipart(req);
    const text = String(fields.text || '').trim();
    if (!text && !file) throw new ApiError(400, 'empty_announcement');
    if (text.length > 4000) throw new ApiError(400, 'text_too_long');
    const photoUrl = file ? await saveImage(file, 'announcements') : null;

    try {
      if (fields.test === 'true') {
        await sendTest({ text, photoUrl, adminId: req.user.telegramId });
        await deleteUpload(photoUrl);
        return { ok: true, test: true };
      }
      const b = await startBroadcast({ text, photoUrl, by: req.user.telegramId });
      return { ok: true, id: String(b._id), total: b.total };
    } catch (e) {
      await deleteUpload(photoUrl);
      throw e;
    }
  });
}
